:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --accent-hover: #ff6b81;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --shadow: #0f0f1a;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  background-image: radial-gradient(circle at 20% 30%, #2a2a4a 1px, transparent 1px);
  background-size: 24px 24px;
  font-family: 'Courier New', Courier, monospace;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border: 4px solid var(--accent);
  box-shadow: 8px 8px 0 var(--shadow);
  padding: 32px 24px;
  max-width: 420px;
  width: 100%;
  text-align: center;
  image-rendering: pixelated;
}

.title {
  font-size: 1.5rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 24px;
}

.mode-switch {
  display: flex;
  gap: 8px;
  justify-content: center;
  margin-bottom: 24px;
}

.mode-btn {
  background: transparent;
  border: 3px solid var(--muted);
  color: var(--muted);
  font-family: inherit;
  font-size: 1rem;
  padding: 8px 16px;
  cursor: pointer;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
  image-rendering: pixelated;
}

.mode-btn:hover {
  border-color: var(--accent-hover);
  color: var(--accent-hover);
}

.mode-btn:focus-visible {
  outline: 3px solid var(--accent-hover);
  outline-offset: 2px;
}

.mode-btn:active {
  transform: translate(2px, 2px);
}

.mode-btn.active {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--card);
}

.timer-display {
  font-size: 4.5rem;
  font-weight: bold;
  letter-spacing: 4px;
  margin: 24px 0;
  color: var(--text);
  text-shadow: 4px 4px 0 var(--shadow);
  image-rendering: pixelated;
  line-height: 1;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  margin-bottom: 24px;
  flex-wrap: wrap;
}

.ctrl-btn {
  background: var(--accent);
  border: 3px solid var(--accent);
  color: var(--card);
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  padding: 12px 20px;
  cursor: pointer;
  box-shadow: 4px 4px 0 var(--shadow);
  transition: background 0.15s, transform 0.05s;
  image-rendering: pixelated;
  min-width: 80px;
}

.ctrl-btn:hover {
  background: var(--accent-hover);
  border-color: var(--accent-hover);
}

.ctrl-btn:focus-visible {
  outline: 3px solid var(--accent-hover);
  outline-offset: 2px;
}

.ctrl-btn:active {
  transform: translate(4px, 4px);
  box-shadow: none;
}

.ctrl-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
  box-shadow: 4px 4px 0 var(--shadow);
}

.status {
  font-size: 1rem;
  color: var(--muted);
  min-height: 1.5em;
}

@media (max-width: 400px) {
  .timer-display {
    font-size: 3.5rem;
  }
  .card {
    padding: 24px 16px;
  }
  .ctrl-btn {
    min-width: 70px;
    padding: 10px 14px;
  }
  .mode-btn {
    padding: 6px 12px;
    font-size: 0.9rem;
  }
}

const WORK_SECONDS = 25 * 60;
const BREAK_SECONDS = 5 * 60;

const timerEl = document.getElementById('timer');
const statusEl = document.getElementById('status');
const startBtn = document.getElementById('startBtn');
const pauseBtn = document.getElementById('pauseBtn');
const resetBtn = document.getElementById('resetBtn');
const workModeBtn = document.getElementById('workMode');
const breakModeBtn = document.getElementById('breakMode');

let mode = 'work';
let totalSeconds = WORK_SECONDS;
let remaining = WORK_SECONDS;
let intervalId = null;
let endTime = 0;
let pausedRemaining = null;

function formatTime(seconds) {
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
}

function updateDisplay() {
  timerEl.textContent = formatTime(remaining);
}

function setStatus(text) {
  statusEl.textContent = text;
}

function stopTimer() {
  if (intervalId !== null) {
    clearInterval(intervalId);
    intervalId = null;
  }
}

function tick() {
  const now = Date.now();
  const secsLeft = Math.max(0, Math.round((endTime - now) / 1000));
  if (secsLeft !== remaining) {
    remaining = secsLeft;
    updateDisplay();
  }
  if (secsLeft <= 0) {
    stopTimer();
    remaining = 0;
    updateDisplay();
    if (mode === 'work') {
      setStatus('Work session complete! Time for a break.');
      switchMode('break', false);
    } else {
      setStatus('Break over! Ready to focus again.');
      switchMode('work', false);
    }
  }
}

function startTimer() {
  if (intervalId !== null) return;
  if (remaining <= 0) {
    resetTimer();
  }
  if (pausedRemaining !== null) {
    remaining = pausedRemaining;
    pausedRemaining = null;
    updateDisplay();
  }
  endTime = Date.now() + remaining * 1000;
  intervalId = setInterval(tick, 200);
  setStatus(mode === 'work' ? 'Focusing...' : 'On a break...');
}

function pauseTimer() {
  if (intervalId === null) return;
  stopTimer();
  const now = Date.now();
  pausedRemaining = Math.max(0, Math.round((endTime - now) / 1000));
  remaining = pausedRemaining;
  updateDisplay();
  setStatus('Paused');
}

function resetTimer() {
  stopTimer();
  pausedRemaining = null;
  remaining = totalSeconds;
  updateDisplay();
  setStatus(mode === 'work' ? 'Ready to focus' : 'Ready for a break');
}

function switchMode(newMode, reset = true) {
  mode = newMode;
  if (mode === 'work') {
    totalSeconds = WORK_SECONDS;
    workModeBtn.classList.add('active');
    workModeBtn.setAttribute('aria-pressed', 'true');
    breakModeBtn.classList.remove('active');
    breakModeBtn.setAttribute('aria-pressed', 'false');
  } else {
    totalSeconds = BREAK_SECONDS;
    breakModeBtn.classList.add('active');
    breakModeBtn.setAttribute('aria-pressed', 'true');
    workModeBtn.classList.remove('active');
    workModeBtn.setAttribute('aria-pressed', 'false');
  }
  if (reset) {
    resetTimer();
  } else {
    remaining = totalSeconds;
    updateDisplay();
  }
}

startBtn.addEventListener('click', startTimer);
pauseBtn.addEventListener('click', pauseTimer);
resetBtn.addEventListener('click', resetTimer);
workModeBtn.addEventListener('click', () => switchMode('work'));
breakModeBtn.addEventListener('click', () => switchMode('break'));

updateDisplay();
setStatus('Ready to focus');
